// Importing necessary modules and components
import React, { useState, useEffect } from 'react';
import '../CSS/hero.css';

// Defining the HeroSection component
function HeroSection() {
  // Setting up state for the movie data
  const [movie, setMovie] = useState({});

  // Defining a function to fetch movie data from the TMDB API
  const fetchMovie = async () => {
    // Getting a random page number from 1 to 10
    const page = Math.floor(Math.random() * 10) + 1;
    // Getting the popular movies from the TMDB API
    const response = await fetch(
      `https://api.themoviedb.org/3/movie/popular?api_key=499d99db6ce23991d21afde0deede0f1&language=en-US&page=${page}`
    );
    const data = await response.json();
    // Getting a random movie from the popular movies
    const movies = data.results;
    const index = Math.floor(Math.random() * movies.length);
    const movie = movies[index];
    // Setting the movie data to the state
    setMovie(movie);
  };

  // Fetching movie data when the component mounts
  useEffect(() => {
    fetchMovie();
  }, []);

  // Rendering the hero section with a poster and relevant information
  return (
    <section className="hero-section">
      {movie && (
        <div className="hero-content">
          <div className="hero-poster">
            <img
              src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`}
              alt={movie.title}
            />
          </div>
          <div className="hero-info">
            <h1>{movie.title}</h1>
            <p>{movie.overview}</p>
            <div className="hero-details">
              <span>{movie.vote_average} / 10</span>
              <span>{movie.release_date}</span>
              <span>
                {movie.genres &&
                  movie.genres.map((genre) => genre.name).join(", ")}
              </span>
            </div>
            <div className="hero-buttons">
              <button>Play Now</button>
              <button>Watch Trailer</button>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

// Exporting the HeroSection component as the default export
export default HeroSection;


